window.CLEAR_CODE.register("runtime/clear/model/target_flow.py",{"text":"\"\"\"CLEAR's task-independent selected-object, order-conditioned target flow.\n\nFlow time is generative time, not controller execution time. Static observations\nare available at every rank; later generated targets are not. Domain adapters\nprovide object/context tokens and interpret/project the final configuration code.\n\"\"\"\nimport math\n\nimport torch\nfrom torch import nn\n\nfrom clear.model.affordance_transformer import AffordanceTransformer\nfrom clear.model.causal_velocity_field import causal_bias, causal_mask\n\n\ndef selection_mask(logits, available):\n    return available \u0026 (logits \u003e 0)\n\n\ndef priority_scale(raw, minimum=0.05, maximum=0.5):\n    \"\"\"Smooth bounded Gaussian scale; no hard-clamp dead zone.\"\"\"\n    return minimum + (maximum - minimum) * torch.sigmoid(raw)\n\n\ndef selected_ranks(rank, available):\n    n = rank.shape[-1]\n    selected = available \u0026 (rank \u003e= 0) \u0026 (rank \u003c n)\n    # zeros_like+n rather than full_like(rank, n): identical result, but the NPU\n    # compiler's tvm frontend mishandles full_like with a scalar fill.\n    return torch.where(selected, rank, torch.zeros_like(rank) + n), selected\n\n\ndef rank_selected(priority, selected, limit=None):\n    \"\"\"Ascending sampled priorities; omitted objects use the N sentinel.\"\"\"\n    n = priority.shape[-1]\n    if limit is not None and limit \u003c 0:\n        raise ValueError(\"interaction limit must be nonnegative\")\n    order = priority.masked_fill(~selected, float('inf')).argsort(dim=-1, stable=True)\n    rank = torch.empty_like(order).scatter_(\n        1, order, torch.arange(n, device=order.device).expand_as(order))\n    active = selected \u0026 (rank \u003c (n if limit is None else limit))\n    return torch.where(active, rank, torch.full_like(rank, n)), active\n\n\ndef time_embedding(t, dim):\n    half = dim // 2\n    freqs = torch.exp(-math.log(1000.0) * torch.arange(half, device=t.device, dtype=t.dtype) / max(1, half - 1))\n    a = t[..., None] * freqs\n    return torch.cat([a.sin(), a.cos()], dim=-1)\n\n\ndef target_velocity(static, context, scene, g_t, t, rank, available,\n                    cfg_in, trunk, head, time_dim, causal=True, key_mask=None,\n                    causal_bias_slope=0.0):\n    \"\"\"Shared Stage B implementation; modules remain owned by each checkpoint.\n\n    `key_mask` (b, 1 + n + s + n) bool marks keys that exist: padded object or\n    scene slots are never read. None keeps the fixed-size behaviour unchanged.\n\n    `causal_bias_slope`: soft-causal ablation (see causal_velocity_field.\n    causal_bias). Only meaningful with causal=False -- it grades the\n    movable-to-movable penalty instead of leaving it at zero. 0.0 (default)\n    is a no-op, byte-for-byte the pre-existing behaviour.\n    \"\"\"\n    rank, selected = selected_ranks(rank, available)\n    g_t = torch.where(selected[..., None], g_t, torch.zeros_like(g_t))\n    b, n, _ = static.shape\n    te = time_embedding(t, time_dim)[:, None].expand(b, n, time_dim)\n    obj = cfg_in(torch.cat([static, g_t, te], dim=-1))\n    # A rank restriction applies to generated decisions, never to currently\n    # observed geometry. Separate read-only copies expose ALL observed objects,\n    # including selected objects whose generated targets must remain hidden.\n    observed = cfg_in(torch.cat([static, torch.zeros_like(g_t), te], dim=-1))\n    tokens = torch.cat([context, obj, scene, observed], dim=1)\n    mask = causal_mask(rank, selected, scene.shape[1] + n, causal=causal)\n    bias = (causal_bias(rank, selected, scene.shape[1] + n, causal_bias_slope)\n            if causal_bias_slope else None)\n    if key_mask is not None:\n        if key_mask.shape != mask.shape[:2]:\n            raise ValueError(\"key_mask must cover context, objects, scene and observed copies\")\n        mask = mask | ~key_mask[:, None, :]\n    return head(trunk(tokens, mask=mask, bias=bias)[:, 1:1 + n])\n\n\nclass RankCausalTargetFlow(nn.Module):\n    def __init__(self, dim, target_dim, depth=4, heads=4, dim_head=32, causal=True,\n                 causal_bias_slope=0.0):\n        super().__init__()\n        if dim % 4:\n            raise ValueError(\"target flow dim must be divisible by 4\")\n        self.dim, self.target_dim, self.causal = dim, target_dim, causal\n        self.noise_std = 1.0\n        self.causal_bias_slope = float(causal_bias_slope)  # soft-causal ablation, see causal_velocity_field.causal_bias\n        self.cfg_in = nn.Sequential(nn.Linear(dim + target_dim + dim // 2, dim),\n                                    nn.GELU(), nn.Linear(dim, dim))\n        self.trunk = AffordanceTransformer(dim, depth=depth, heads=heads, dim_head=dim_head)\n        self.head = nn.Sequential(nn.LayerNorm(dim), nn.Linear(dim, dim), nn.GELU(),\n                                  nn.Linear(dim, target_dim))\n\n    def forward(self, static, context, scene, g_t, t, rank, selected, key_mask=None):\n        return target_velocity(static, context, scene, g_t, t, rank, selected,\n                               self.cfg_in, self.trunk, self.head, self.dim // 2, self.causal,\n                               key_mask=key_mask, causal_bias_slope=self.causal_bias_slope)\n\n    @torch.no_grad()\n    def sample(self, static, context, scene, rank, selected, n_steps=30, generator=None,\n               key_mask=None, trace=None):\n        \"\"\"`trace`, if a list, receives (t, state) at every Euler step and at t=1.\n\n        The states are the generator's own intermediates. They exist so a figure\n        can show the flow evolving instead of an interpolation of its endpoint;\n        nothing in the planner reads them and the default path is unchanged.\n        \"\"\"\n        if n_steps \u003c= 0:\n            raise ValueError(\"n_steps must be positive\")\n        rank, selected = selected_ranks(rank, selected)\n        g = torch.randn(*static.shape[:2], self.target_dim, device=static.device,\n                        dtype=static.dtype, generator=generator) * self.noise_std\n        g = torch.where(selected[..., None], g, torch.zeros_like(g))\n        for k in range(n_steps):\n            t = torch.full((static.shape[0],), k / n_steps, device=static.device, dtype=static.dtype)\n            if trace is not None:\n                trace.append((k / n_steps, g.detach().clone()))\n            v = self(static, context, scene, g, t, rank, selected, key_mask=key_mask)\n            g = g + torch.where(selected[..., None], v, torch.zeros_like(v)) / n_steps\n        if trace is not None:\n            trace.append((1.0, g.detach().clone()))\n        return g\n","lines":["\u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;CLEAR\u0026#x27;s task-independent selected-object, order-conditioned target flow.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eFlow time is generative time, not controller execution time. Static observations\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eare available at every rank; later generated targets are not. Domain adapters\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eprovide object/context tokens and interpret/project the final configuration code.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","\u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e math","","\u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e torch","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e torch \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e nn","","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.affordance_transformer \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e AffordanceTransformer","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.causal_velocity_field \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e causal_bias, causal_mask","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eselection_mask\u003c/span\u003e(logits, available):","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e available \u0026amp; (logits \u0026gt; \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003epriority_scale\u003c/span\u003e(raw, minimum=\u003cspan class=\"tok-number\"\u003e0.05\u003c/span\u003e, maximum=\u003cspan class=\"tok-number\"\u003e0.5\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Smooth bounded Gaussian scale; no hard-clamp dead zone.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e minimum + (maximum - minimum) * torch.sigmoid(raw)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eselected_ranks\u003c/span\u003e(rank, available):","    n = rank.shape[-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","    selected = available \u0026amp; (rank \u0026gt;= \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e) \u0026amp; (rank \u0026lt; n)","    \u003cspan class=\"tok-comment\"\u003e# zeros_like+n rather than full_like(rank, n): identical result, but the NPU\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# compiler\u0026#x27;s tvm frontend mishandles full_like with a scalar fill.\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.where(selected, rank, torch.zeros_like(rank) + n), selected","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003erank_selected\u003c/span\u003e(priority, selected, limit=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Ascending sampled priorities; omitted objects use the N sentinel.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    n = priority.shape[-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e limit \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e limit \u0026lt; \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e:","        \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;interaction limit must be nonnegative\u0026quot;\u003c/span\u003e)","    order = priority.masked_fill(~selected, float(\u003cspan class=\"tok-string\"\u003e\u0026#x27;inf\u0026#x27;\u003c/span\u003e)).argsort(dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, stable=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e)","    rank = torch.empty_like(order).scatter_(","        \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, order, torch.arange(n, device=order.device).expand_as(order))","    active = selected \u0026amp; (rank \u0026lt; (n \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e limit \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e limit))","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.where(active, rank, torch.full_like(rank, n)), active","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003etime_embedding\u003c/span\u003e(t, dim):","    half = dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e","    freqs = torch.exp(-math.log(\u003cspan class=\"tok-number\"\u003e1000.0\u003c/span\u003e) * torch.arange(half, device=t.device, dtype=t.dtype) / max(\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, half - \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    a = t[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e] * freqs","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.cat([a.sin(), a.cos()], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003etarget_velocity\u003c/span\u003e(static, context, scene, g_t, t, rank, available,","                    cfg_in, trunk, head, time_dim, causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e, key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","                    causal_bias_slope=\u003cspan class=\"tok-number\"\u003e0.0\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Shared Stage B implementation; modules remain owned by each checkpoint.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `key_mask` (b, 1 + n + s + n) bool marks keys that exist: padded object or\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    scene slots are never read. None keeps the fixed-size behaviour unchanged.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `causal_bias_slope`: soft-causal ablation (see causal_velocity_field.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    causal_bias). Only meaningful with causal=False -- it grades the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    movable-to-movable penalty instead of leaving it at zero. 0.0 (default)\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    is a no-op, byte-for-byte the pre-existing behaviour.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    rank, selected = selected_ranks(rank, available)","    g_t = torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], g_t, torch.zeros_like(g_t))","    b, n, _ = static.shape","    te = time_embedding(t, time_dim)[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e].expand(b, n, time_dim)","    obj = cfg_in(torch.cat([static, g_t, te], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    \u003cspan class=\"tok-comment\"\u003e# A rank restriction applies to generated decisions, never to currently\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# observed geometry. Separate read-only copies expose ALL observed objects,\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# including selected objects whose generated targets must remain hidden.\u003c/span\u003e","    observed = cfg_in(torch.cat([static, torch.zeros_like(g_t), te], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    tokens = torch.cat([context, obj, scene, observed], dim=\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","    mask = causal_mask(rank, selected, scene.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e] + n, causal=causal)","    bias = (causal_bias(rank, selected, scene.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e] + n, causal_bias_slope)","            \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e causal_bias_slope \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e)","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e key_mask \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e key_mask.shape != mask.shape[:\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e]:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;key_mask must cover context, objects, scene and observed copies\u0026quot;\u003c/span\u003e)","        mask = mask | ~key_mask[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e head(trunk(tokens, mask=mask, bias=bias)[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e:\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n])","","","\u003cspan class=\"tok-keyword\"\u003eclass\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eRankCausalTargetFlow\u003c/span\u003e(nn.Module):","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e__init__\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, dim, target_dim, depth=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, heads=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e, dim_head=\u003cspan class=\"tok-number\"\u003e32\u003c/span\u003e, causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e,","                 causal_bias_slope=\u003cspan class=\"tok-number\"\u003e0.0\u003c/span\u003e):","        super().__init__()","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e dim % \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;target flow dim must be divisible by 4\u0026quot;\u003c/span\u003e)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.dim, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.target_dim, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal = dim, target_dim, causal","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.noise_std = \u003cspan class=\"tok-number\"\u003e1.0\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal_bias_slope = float(causal_bias_slope)  \u003cspan class=\"tok-comment\"\u003e# soft-causal ablation, see causal_velocity_field.causal_bias\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.cfg_in = nn.Sequential(nn.Linear(dim + target_dim + dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim),","                                    nn.GELU(), nn.Linear(dim, dim))","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.trunk = AffordanceTransformer(dim, depth=depth, heads=heads, dim_head=dim_head)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.head = nn.Sequential(nn.LayerNorm(dim), nn.Linear(dim, dim), nn.GELU(),","                                  nn.Linear(dim, target_dim))","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eforward\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, static, context, scene, g_t, t, rank, selected, key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e target_velocity(static, context, scene, g_t, t, rank, selected,","                               \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.cfg_in, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.trunk, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.head, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal,","                               key_mask=key_mask, causal_bias_slope=\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal_bias_slope)","","    @torch.no_grad()","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003esample\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, static, context, scene, rank, selected, n_steps=\u003cspan class=\"tok-number\"\u003e30\u003c/span\u003e, generator=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","               key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, trace=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","        \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;`trace`, if a list, receives (t, state) at every Euler step and at t=1.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        The states are the generator\u0026#x27;s own intermediates. They exist so a figure\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        can show the flow evolving instead of an interpolation of its endpoint;\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        nothing in the planner reads them and the default path is unchanged.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e n_steps \u0026lt;= \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;n_steps must be positive\u0026quot;\u003c/span\u003e)","        rank, selected = selected_ranks(rank, selected)","        g = torch.randn(*static.shape[:\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e], \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.target_dim, device=static.device,","                        dtype=static.dtype, generator=generator) * \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.noise_std","        g = torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], g, torch.zeros_like(g))","        \u003cspan class=\"tok-keyword\"\u003efor\u003c/span\u003e k \u003cspan class=\"tok-keyword\"\u003ein\u003c/span\u003e range(n_steps):","            t = torch.full((static.shape[\u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e],), k / n_steps, device=static.device, dtype=static.dtype)","            \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e trace \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","                trace.append((k / n_steps, g.detach().clone()))","            v = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e(static, context, scene, g, t, rank, selected, key_mask=key_mask)","            g = g + torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], v, torch.zeros_like(v)) / n_steps","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e trace \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","            trace.append((\u003cspan class=\"tok-number\"\u003e1.0\u003c/span\u003e, g.detach().clone()))","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e g"],"formatted":{"text":"\"\"\"CLEAR's task-independent selected-object, order-conditioned target flow.\n\nFlow time is generative time, not controller execution time. Static observations\nare available at every rank; later generated targets are not. Domain adapters\nprovide object/context tokens and interpret/project the final configuration code.\n\"\"\"\n\nimport math\n\nimport torch\nfrom torch import nn\n\nfrom clear.model.affordance_transformer import AffordanceTransformer\nfrom clear.model.causal_velocity_field import causal_bias, causal_mask\n\n\ndef selection_mask(logits, available):\n    return available \u0026 (logits \u003e 0)\n\n\ndef priority_scale(raw, minimum=0.05, maximum=0.5):\n    \"\"\"Smooth bounded Gaussian scale; no hard-clamp dead zone.\"\"\"\n    return minimum + (maximum - minimum) * torch.sigmoid(raw)\n\n\ndef selected_ranks(rank, available):\n    n = rank.shape[-1]\n    selected = available \u0026 (rank \u003e= 0) \u0026 (rank \u003c n)\n    # zeros_like+n rather than full_like(rank, n): identical result, but the NPU\n    # compiler's tvm frontend mishandles full_like with a scalar fill.\n    return torch.where(selected, rank, torch.zeros_like(rank) + n), selected\n\n\ndef rank_selected(priority, selected, limit=None):\n    \"\"\"Ascending sampled priorities; omitted objects use the N sentinel.\"\"\"\n    n = priority.shape[-1]\n    if limit is not None and limit \u003c 0:\n        raise ValueError(\"interaction limit must be nonnegative\")\n    order = priority.masked_fill(~selected, float(\"inf\")).argsort(dim=-1, stable=True)\n    rank = torch.empty_like(order).scatter_(\n        1, order, torch.arange(n, device=order.device).expand_as(order)\n    )\n    active = selected \u0026 (rank \u003c (n if limit is None else limit))\n    return torch.where(active, rank, torch.full_like(rank, n)), active\n\n\ndef time_embedding(t, dim):\n    half = dim // 2\n    freqs = torch.exp(\n        -math.log(1000.0)\n        * torch.arange(half, device=t.device, dtype=t.dtype)\n        / max(1, half - 1)\n    )\n    a = t[..., None] * freqs\n    return torch.cat([a.sin(), a.cos()], dim=-1)\n\n\ndef target_velocity(\n    static,\n    context,\n    scene,\n    g_t,\n    t,\n    rank,\n    available,\n    cfg_in,\n    trunk,\n    head,\n    time_dim,\n    causal=True,\n    key_mask=None,\n    causal_bias_slope=0.0,\n):\n    \"\"\"Shared Stage B implementation; modules remain owned by each checkpoint.\n\n    `key_mask` (b, 1 + n + s + n) bool marks keys that exist: padded object or\n    scene slots are never read. None keeps the fixed-size behaviour unchanged.\n\n    `causal_bias_slope`: soft-causal ablation (see causal_velocity_field.\n    causal_bias). Only meaningful with causal=False -- it grades the\n    movable-to-movable penalty instead of leaving it at zero. 0.0 (default)\n    is a no-op, byte-for-byte the pre-existing behaviour.\n    \"\"\"\n    rank, selected = selected_ranks(rank, available)\n    g_t = torch.where(selected[..., None], g_t, torch.zeros_like(g_t))\n    b, n, _ = static.shape\n    te = time_embedding(t, time_dim)[:, None].expand(b, n, time_dim)\n    obj = cfg_in(torch.cat([static, g_t, te], dim=-1))\n    # A rank restriction applies to generated decisions, never to currently\n    # observed geometry. Separate read-only copies expose ALL observed objects,\n    # including selected objects whose generated targets must remain hidden.\n    observed = cfg_in(torch.cat([static, torch.zeros_like(g_t), te], dim=-1))\n    tokens = torch.cat([context, obj, scene, observed], dim=1)\n    mask = causal_mask(rank, selected, scene.shape[1] + n, causal=causal)\n    bias = (\n        causal_bias(rank, selected, scene.shape[1] + n, causal_bias_slope)\n        if causal_bias_slope\n        else None\n    )\n    if key_mask is not None:\n        if key_mask.shape != mask.shape[:2]:\n            raise ValueError(\n                \"key_mask must cover context, objects, scene and observed copies\"\n            )\n        mask = mask | ~key_mask[:, None, :]\n    return head(trunk(tokens, mask=mask, bias=bias)[:, 1 : 1 + n])\n\n\nclass RankCausalTargetFlow(nn.Module):\n    def __init__(\n        self,\n        dim,\n        target_dim,\n        depth=4,\n        heads=4,\n        dim_head=32,\n        causal=True,\n        causal_bias_slope=0.0,\n    ):\n        super().__init__()\n        if dim % 4:\n            raise ValueError(\"target flow dim must be divisible by 4\")\n        self.dim, self.target_dim, self.causal = dim, target_dim, causal\n        self.noise_std = 1.0\n        self.causal_bias_slope = float(\n            causal_bias_slope\n        )  # soft-causal ablation, see causal_velocity_field.causal_bias\n        self.cfg_in = nn.Sequential(\n            nn.Linear(dim + target_dim + dim // 2, dim), nn.GELU(), nn.Linear(dim, dim)\n        )\n        self.trunk = AffordanceTransformer(\n            dim, depth=depth, heads=heads, dim_head=dim_head\n        )\n        self.head = nn.Sequential(\n            nn.LayerNorm(dim),\n            nn.Linear(dim, dim),\n            nn.GELU(),\n            nn.Linear(dim, target_dim),\n        )\n\n    def forward(self, static, context, scene, g_t, t, rank, selected, key_mask=None):\n        return target_velocity(\n            static,\n            context,\n            scene,\n            g_t,\n            t,\n            rank,\n            selected,\n            self.cfg_in,\n            self.trunk,\n            self.head,\n            self.dim // 2,\n            self.causal,\n            key_mask=key_mask,\n            causal_bias_slope=self.causal_bias_slope,\n        )\n\n    @torch.no_grad()\n    def sample(\n        self,\n        static,\n        context,\n        scene,\n        rank,\n        selected,\n        n_steps=30,\n        generator=None,\n        key_mask=None,\n        trace=None,\n    ):\n        \"\"\"`trace`, if a list, receives (t, state) at every Euler step and at t=1.\n\n        The states are the generator's own intermediates. They exist so a figure\n        can show the flow evolving instead of an interpolation of its endpoint;\n        nothing in the planner reads them and the default path is unchanged.\n        \"\"\"\n        if n_steps \u003c= 0:\n            raise ValueError(\"n_steps must be positive\")\n        rank, selected = selected_ranks(rank, selected)\n        g = (\n            torch.randn(\n                *static.shape[:2],\n                self.target_dim,\n                device=static.device,\n                dtype=static.dtype,\n                generator=generator\n            )\n            * self.noise_std\n        )\n        g = torch.where(selected[..., None], g, torch.zeros_like(g))\n        for k in range(n_steps):\n            t = torch.full(\n                (static.shape[0],),\n                k / n_steps,\n                device=static.device,\n                dtype=static.dtype,\n            )\n            if trace is not None:\n                trace.append((k / n_steps, g.detach().clone()))\n            v = self(static, context, scene, g, t, rank, selected, key_mask=key_mask)\n            g = g + torch.where(selected[..., None], v, torch.zeros_like(v)) / n_steps\n        if trace is not None:\n            trace.append((1.0, g.detach().clone()))\n        return g\n","lines":["\u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;CLEAR\u0026#x27;s task-independent selected-object, order-conditioned target flow.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eFlow time is generative time, not controller execution time. Static observations\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eare available at every rank; later generated targets are not. Domain adapters\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003eprovide object/context tokens and interpret/project the final configuration code.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","","\u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e math","","\u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e torch","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e torch \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e nn","","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.affordance_transformer \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e AffordanceTransformer","\u003cspan class=\"tok-keyword\"\u003efrom\u003c/span\u003e clear.model.causal_velocity_field \u003cspan class=\"tok-keyword\"\u003eimport\u003c/span\u003e causal_bias, causal_mask","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eselection_mask\u003c/span\u003e(logits, available):","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e available \u0026amp; (logits \u0026gt; \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003epriority_scale\u003c/span\u003e(raw, minimum=\u003cspan class=\"tok-number\"\u003e0.05\u003c/span\u003e, maximum=\u003cspan class=\"tok-number\"\u003e0.5\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Smooth bounded Gaussian scale; no hard-clamp dead zone.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e minimum + (maximum - minimum) * torch.sigmoid(raw)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eselected_ranks\u003c/span\u003e(rank, available):","    n = rank.shape[-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","    selected = available \u0026amp; (rank \u0026gt;= \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e) \u0026amp; (rank \u0026lt; n)","    \u003cspan class=\"tok-comment\"\u003e# zeros_like+n rather than full_like(rank, n): identical result, but the NPU\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# compiler\u0026#x27;s tvm frontend mishandles full_like with a scalar fill.\u003c/span\u003e","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.where(selected, rank, torch.zeros_like(rank) + n), selected","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003erank_selected\u003c/span\u003e(priority, selected, limit=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Ascending sampled priorities; omitted objects use the N sentinel.\u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    n = priority.shape[-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e]","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e limit \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eand\u003c/span\u003e limit \u0026lt; \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e:","        \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;interaction limit must be nonnegative\u0026quot;\u003c/span\u003e)","    order = priority.masked_fill(~selected, float(\u003cspan class=\"tok-string\"\u003e\u0026quot;inf\u0026quot;\u003c/span\u003e)).argsort(dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, stable=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e)","    rank = torch.empty_like(order).scatter_(","        \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, order, torch.arange(n, device=order.device).expand_as(order)","    )","    active = selected \u0026amp; (rank \u0026lt; (n \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e limit \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e limit))","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.where(active, rank, torch.full_like(rank, n)), active","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003etime_embedding\u003c/span\u003e(t, dim):","    half = dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e","    freqs = torch.exp(","        -math.log(\u003cspan class=\"tok-number\"\u003e1000.0\u003c/span\u003e)","        * torch.arange(half, device=t.device, dtype=t.dtype)","        / max(\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e, half - \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","    )","    a = t[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e] * freqs","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e torch.cat([a.sin(), a.cos()], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","","","\u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003etarget_velocity\u003c/span\u003e(","    static,","    context,","    scene,","    g_t,","    t,","    rank,","    available,","    cfg_in,","    trunk,","    head,","    time_dim,","    causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e,","    key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","    causal_bias_slope=\u003cspan class=\"tok-number\"\u003e0.0\u003c/span\u003e,","):","    \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;Shared Stage B implementation; modules remain owned by each checkpoint.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `key_mask` (b, 1 + n + s + n) bool marks keys that exist: padded object or\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    scene slots are never read. None keeps the fixed-size behaviour unchanged.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    `causal_bias_slope`: soft-causal ablation (see causal_velocity_field.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    causal_bias). Only meaningful with causal=False -- it grades the\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    movable-to-movable penalty instead of leaving it at zero. 0.0 (default)\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    is a no-op, byte-for-byte the pre-existing behaviour.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e    \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","    rank, selected = selected_ranks(rank, available)","    g_t = torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], g_t, torch.zeros_like(g_t))","    b, n, _ = static.shape","    te = time_embedding(t, time_dim)[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e].expand(b, n, time_dim)","    obj = cfg_in(torch.cat([static, g_t, te], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    \u003cspan class=\"tok-comment\"\u003e# A rank restriction applies to generated decisions, never to currently\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# observed geometry. Separate read-only copies expose ALL observed objects,\u003c/span\u003e","    \u003cspan class=\"tok-comment\"\u003e# including selected objects whose generated targets must remain hidden.\u003c/span\u003e","    observed = cfg_in(torch.cat([static, torch.zeros_like(g_t), te], dim=-\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e))","    tokens = torch.cat([context, obj, scene, observed], dim=\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e)","    mask = causal_mask(rank, selected, scene.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e] + n, causal=causal)","    bias = (","        causal_bias(rank, selected, scene.shape[\u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e] + n, causal_bias_slope)","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e causal_bias_slope","        \u003cspan class=\"tok-keyword\"\u003eelse\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e","    )","    \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e key_mask \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e key_mask.shape != mask.shape[:\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e]:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(","                \u003cspan class=\"tok-string\"\u003e\u0026quot;key_mask must cover context, objects, scene and observed copies\u0026quot;\u003c/span\u003e","            )","        mask = mask | ~key_mask[:, \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e, :]","    \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e head(trunk(tokens, mask=mask, bias=bias)[:, \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e : \u003cspan class=\"tok-number\"\u003e1\u003c/span\u003e + n])","","","\u003cspan class=\"tok-keyword\"\u003eclass\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eRankCausalTargetFlow\u003c/span\u003e(nn.Module):","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003e__init__\u003c/span\u003e(","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e,","        dim,","        target_dim,","        depth=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e,","        heads=\u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e,","        dim_head=\u003cspan class=\"tok-number\"\u003e32\u003c/span\u003e,","        causal=\u003cspan class=\"tok-keyword\"\u003eTrue\u003c/span\u003e,","        causal_bias_slope=\u003cspan class=\"tok-number\"\u003e0.0\u003c/span\u003e,","    ):","        super().__init__()","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e dim % \u003cspan class=\"tok-number\"\u003e4\u003c/span\u003e:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;target flow dim must be divisible by 4\u0026quot;\u003c/span\u003e)","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.dim, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.target_dim, \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal = dim, target_dim, causal","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.noise_std = \u003cspan class=\"tok-number\"\u003e1.0\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal_bias_slope = float(","            causal_bias_slope","        )  \u003cspan class=\"tok-comment\"\u003e# soft-causal ablation, see causal_velocity_field.causal_bias\u003c/span\u003e","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.cfg_in = nn.Sequential(","            nn.Linear(dim + target_dim + dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e, dim), nn.GELU(), nn.Linear(dim, dim)","        )","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.trunk = AffordanceTransformer(","            dim, depth=depth, heads=heads, dim_head=dim_head","        )","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.head = nn.Sequential(","            nn.LayerNorm(dim),","            nn.Linear(dim, dim),","            nn.GELU(),","            nn.Linear(dim, target_dim),","        )","","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003eforward\u003c/span\u003e(\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e, static, context, scene, g_t, t, rank, selected, key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e):","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e target_velocity(","            static,","            context,","            scene,","            g_t,","            t,","            rank,","            selected,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.cfg_in,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.trunk,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.head,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.dim // \u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e,","            \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal,","            key_mask=key_mask,","            causal_bias_slope=\u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.causal_bias_slope,","        )","","    @torch.no_grad()","    \u003cspan class=\"tok-keyword\"\u003edef\u003c/span\u003e \u003cspan class=\"tok-definition\"\u003esample\u003c/span\u003e(","        \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e,","        static,","        context,","        scene,","        rank,","        selected,","        n_steps=\u003cspan class=\"tok-number\"\u003e30\u003c/span\u003e,","        generator=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","        key_mask=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","        trace=\u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e,","    ):","        \u003cspan class=\"tok-string\"\u003e\u0026quot;\u0026quot;\u0026quot;`trace`, if a list, receives (t, state) at every Euler step and at t=1.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        The states are the generator\u0026#x27;s own intermediates. They exist so a figure\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        can show the flow evolving instead of an interpolation of its endpoint;\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        nothing in the planner reads them and the default path is unchanged.\u003c/span\u003e","\u003cspan class=\"tok-string\"\u003e        \u0026quot;\u0026quot;\u0026quot;\u003c/span\u003e","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e n_steps \u0026lt;= \u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e:","            \u003cspan class=\"tok-keyword\"\u003eraise\u003c/span\u003e ValueError(\u003cspan class=\"tok-string\"\u003e\u0026quot;n_steps must be positive\u0026quot;\u003c/span\u003e)","        rank, selected = selected_ranks(rank, selected)","        g = (","            torch.randn(","                *static.shape[:\u003cspan class=\"tok-number\"\u003e2\u003c/span\u003e],","                \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.target_dim,","                device=static.device,","                dtype=static.dtype,","                generator=generator","            )","            * \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e.noise_std","        )","        g = torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], g, torch.zeros_like(g))","        \u003cspan class=\"tok-keyword\"\u003efor\u003c/span\u003e k \u003cspan class=\"tok-keyword\"\u003ein\u003c/span\u003e range(n_steps):","            t = torch.full(","                (static.shape[\u003cspan class=\"tok-number\"\u003e0\u003c/span\u003e],),","                k / n_steps,","                device=static.device,","                dtype=static.dtype,","            )","            \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e trace \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","                trace.append((k / n_steps, g.detach().clone()))","            v = \u003cspan class=\"tok-builtin\"\u003eself\u003c/span\u003e(static, context, scene, g, t, rank, selected, key_mask=key_mask)","            g = g + torch.where(selected[..., \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e], v, torch.zeros_like(v)) / n_steps","        \u003cspan class=\"tok-keyword\"\u003eif\u003c/span\u003e trace \u003cspan class=\"tok-keyword\"\u003eis\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003enot\u003c/span\u003e \u003cspan class=\"tok-keyword\"\u003eNone\u003c/span\u003e:","            trace.append((\u003cspan class=\"tok-number\"\u003e1.0\u003c/span\u003e, g.detach().clone()))","        \u003cspan class=\"tok-keyword\"\u003ereturn\u003c/span\u003e g"],"symbols":[{"name":"selection_mask","start":17,"end":18},{"name":"priority_scale","start":21,"end":23},{"name":"selected_ranks","start":26,"end":31},{"name":"rank_selected","start":34,"end":44},{"name":"time_embedding","start":47,"end":55},{"name":"target_velocity","start":58,"end":106},{"name":"RankCausalTargetFlow","start":109,"end":205},{"name":"RankCausalTargetFlow.__init__","start":110,"end":139},{"name":"RankCausalTargetFlow.forward","start":141,"end":157},{"name":"RankCausalTargetFlow.sample","start":159,"end":205}]}});
